/* ASAP INJECTION: The Morphogenic Groove */
@keyframes groovePulse {
  0%, 100% {
    text-shadow: 0 0 8px rgba(255, 120, 50, 0.5), 0 0 15px rgba(255, 50, 0, 0.3);
    transform: scale(1);
  }
  50% {
    text-shadow: 0 0 15px rgba(255, 150, 50, 0.8), 0 0 25px rgba(255, 80, 0, 0.6);
    transform: scale(1.002);
  }
}

.ai-message, p {
  animation: groovePulse 3.5s infinite ease-in-out;
  letter-spacing: 0.3px;
  transition: all 0.3s ease;
}

body {
  animation: temporalPulse 4s infinite alternate ease-in-out;
}

@keyframes temporalPulse {
  0% {
    box-shadow: inset 0 0 50px rgba(138, 43, 226, 0.2);
    background-color: rgba(10, 0, 20, 1);
  }
  100% {
    box-shadow: inset 0 0 150px rgba(138, 43, 226, 0.6);
    background-color: rgba(20, 0, 40, 1);
  }
}
